import openpyxl
base='/tmp/llm_rollout_yxem2dou'
out=f'{base}/周生产计划表_template_8195_filled.xlsx'
gold='/mnt/hhq/data/data_pipeline/generated_tasks/route_b_dataset_tables_excel_batch1/passed/template/周生产计划表_template_8195_golden.xlsx'
wbo=openpyxl.load_workbook(out); wso=wbo['Sheet1']
wbg=openpyxl.load_workbook(gold); wsg=wbg['Sheet1']

diffs=[]
for r in range(1, max(wso.max_row, wsg.max_row)+1):
    for c in range(1, max(wso.max_column, wsg.max_column)+1):
        vo=wso.cell(r,c).value
        vg=wsg.cell(r,c).value
        if vo!=vg:
            diffs.append((openpyxl.utils.get_column_letter(c)+str(r), vo, vg))
print('value diffs', len(diffs))
for d in diffs[:50]: print(d)

# compare number formats & fills for populated range
fmt_diffs=[]
for r in range(1, wso.max_row+1):
    for c in range(1, wso.max_column+1):
        co=wso.cell(r,c); cg=wsg.cell(r,c)
        if co.number_format != cg.number_format:
            fmt_diffs.append((openpyxl.utils.get_column_letter(c)+str(r),'numfmt',co.number_format,cg.number_format))
        if co.fill.fill_type != cg.fill.fill_type:
            fmt_diffs.append((openpyxl.utils.get_column_letter(c)+str(r),'filltype',co.fill.fill_type,cg.fill.fill_type))
        if co.fill.fgColor.rgb != cg.fill.fgColor.rgb:
            fmt_diffs.append((openpyxl.utils.get_column_letter(c)+str(r),'fg',co.fill.fgColor.rgb,cg.fill.fgColor.rgb))
print('fmt diffs', len(fmt_diffs))
for d in fmt_diffs[:50]: print(d)
